/home/cva6/core/cva6_mmu/cva6_mmu.sv
/home/cva6/.tb_misaligned_lsu_no_spurious_ptw/tb_misaligned_mmu.sv
EOF

set +e
timeout 1200s "$VERILATOR_CMD" --binary --timing -Wno-fatal \
