  logic [CVA6Cfg.NrIssuePorts-1:0] rvfi_is_compressed_o;
  riscv::priv_lvl_t priv_lvl_i;
  logic v_i;
  riscv::xs_t fs_i;
  riscv::xs_t vfs_i;
  logic [2:0] frm_i;
  riscv::xs_t vs_i;
  logic [1:0] irq_i;
  irq_ctrl_t irq_ctrl_i;
  logic debug_mode_i;
  logic tvm_i;
  logic tw_i;
  logic vtw_i;
  logic tsr_i;
  logic hu_i;
  riscv::cbie_t mcbie_i;
