+    }
+    //Try to program kv dest incorrectly
+    if (!privkey.kv_intf){
+        // set privkey DEST to write
+        lsu_write_32(CLP_ECC_REG_ECC_KV_WR_PKEY_CTRL, (ECC_REG_ECC_KV_WR_PKEY_CTRL_WRITE_EN_MASK |
