#!/bin/bash
set -euo pipefail

cd /home/caliptra-rtl

workdir=/home/caliptra-rtl/.hwe_pr1073_axi4_to_ahb
mkdir -p "$workdir"

cat > "$workdir/axi4_to_ahb_stream_rd_stall_tb.sv" <<'SV'
module axi4_to_ahb_stream_rd_stall_tb;
  timeunit 1ns;
  timeprecision 100ps;

  localparam logic [31:0] FIRST_ADDR  = 32'h0000_1000;
  localparam logic [31:0] SECOND_ADDR = 32'h0000_1004;

  logic clk = 1'b0;
  logic rst_l = 1'b0;
  logic free_clk;
  logic scan_mode;
  logic bus_clk_en;
  logic clk_override;
  logic dec_tlu_force_halt;

  logic        axi_awvalid;
  logic        axi_awready;
  logic [0:0]  axi_awid;
  logic [31:0] axi_awaddr;
  logic [2:0]  axi_awsize;
  logic [2:0]  axi_awprot;

  logic        axi_wvalid;
  logic        axi_wready;
  logic [63:0] axi_wdata;
  logic [7:0]  axi_wstrb;
  logic        axi_wlast;

  logic        axi_bvalid;
  logic        axi_bready;
  logic [1:0]  axi_bresp;
  logic [0:0]  axi_bid;

  logic        axi_arvalid;
  logic        axi_arready;
  logic [0:0]  axi_arid;
  logic [31:0] axi_araddr;
  logic [2:0]  axi_arsize;
  logic [2:0]  axi_arprot;

  logic        axi_rvalid;
  logic        axi_rready;
  logic [0:0]  axi_rid;
  logic [63:0] axi_rdata;
  logic [1:0]  axi_rresp;
  logic        axi_rlast;

  logic [31:0] ahb_haddr;
  logic [2:0]  ahb_hburst;
  logic        ahb_hmastlock;
  logic [3:0]  ahb_hprot;
  logic [2:0]  ahb_hsize;
  logic [1:0]  ahb_htrans;
  logic        ahb_hwrite;
  logic [63:0] ahb_hwdata;
  logic [63:0] ahb_hrdata;
  logic        ahb_hready;
  logic        ahb_hresp;

  always #5 clk = ~clk;

  assign free_clk = clk;

  axi4_to_ahb #(
    .TAG(1)
  ) dut (
    .clk(clk),
    .free_clk(free_clk),
    .rst_l(rst_l),
    .scan_mode(scan_mode),
    .bus_clk_en(bus_clk_en),
    .clk_override(clk_override),
    .dec_tlu_force_halt(dec_tlu_force_halt),
    .axi_awvalid(axi_awvalid),
    .axi_awready(axi_awready),
    .axi_awid(axi_awid),
    .axi_awaddr(axi_awaddr),
    .axi_awsize(axi_awsize),
    .axi_awprot(axi_awprot),
    .axi_wvalid(axi_wvalid),
    .axi_wready(axi_wready),
    .axi_wdata(axi_wdata),
    .axi_wstrb(axi_wstrb),
    .axi_wlast(axi_wlast),
    .axi_bvalid(axi_bvalid),
    .axi_bready(axi_bready),
    .axi_bresp(axi_bresp),
    .axi_bid(axi_bid),
    .axi_arvalid(axi_arvalid),
    .axi_arready(axi_arready),
    .axi_arid(axi_arid),
    .axi_araddr(axi_araddr),
    .axi_arsize(axi_arsize),
    .axi_arprot(axi_arprot),
    .axi_rvalid(axi_rvalid),
    .axi_rready(axi_rready),
    .axi_rid(axi_rid),
    .axi_rdata(axi_rdata),
    .axi_rresp(axi_rresp),
    .axi_rlast(axi_rlast),
    .ahb_haddr(ahb_haddr),
    .ahb_hburst(ahb_hburst),
    .ahb_hmastlock(ahb_hmastlock),
    .ahb_hprot(ahb_hprot),
    .ahb_hsize(ahb_hsize),
    .ahb_htrans(ahb_htrans),
    .ahb_hwrite(ahb_hwrite),
    .ahb_hwdata(ahb_hwdata),
    .ahb_hrdata(ahb_hrdata),
    .ahb_hready(ahb_hready),
    .ahb_hresp(ahb_hresp)
  );

  initial begin
    scan_mode = 1'b0;
    bus_clk_en = 1'b1;
    clk_override = 1'b0;
    dec_tlu_force_halt = 1'b0;

    axi_awvalid = 1'b0;
    axi_awid = '0;
    axi_awaddr = '0;
    axi_awsize = 3'b010;
    axi_awprot = '0;
    axi_wvalid = 1'b0;
    axi_wdata = '0;
    axi_wstrb = '0;
    axi_wlast = 1'b0;
    axi_bready = 1'b1;

    axi_arvalid = 1'b0;
    axi_arid = '0;
    axi_araddr = '0;
    axi_arsize = 3'b010;
    axi_arprot = '0;
    axi_rready = 1'b1;

    ahb_hrdata = 64'h0123_4567_89ab_cdef;
    ahb_hready = 1'b1;
    ahb_hresp = 1'b0;

    repeat (2) @(negedge clk);
    rst_l = 1'b1;
    repeat (2) @(posedge clk);

    @(negedge clk);
    axi_arvalid = 1'b1;
    axi_araddr = FIRST_ADDR;
    #1;
    if (ahb_htrans !== 2'b10 || ahb_haddr !== FIRST_ADDR) begin
      $display("First read launch mismatch: htrans=%b haddr=%08x", ahb_htrans, ahb_haddr);
      $fatal(1, "first read launch mismatch");
    end

    @(posedge clk);
    @(negedge clk);
    axi_araddr = SECOND_ADDR;
    ahb_hready = 1'b0;
    #1;
    if (ahb_htrans !== 2'b10 || ahb_haddr !== SECOND_ADDR) begin
      $display("Second read launch mismatch: htrans=%b haddr=%08x", ahb_htrans, ahb_haddr);
      $fatal(1, "second read launch mismatch");
    end

    @(posedge clk);
    #1;
    if (ahb_htrans !== 2'b10) begin
      $display("Stalled stream read changed HTRANS: htrans=%b haddr=%08x", ahb_htrans, ahb_haddr);
      $fatal(1, "stalled stream read changed HTRANS");
    end
    if (ahb_haddr !== SECOND_ADDR) begin
      $display("Stalled stream read lost address bits: htrans=%b haddr=%08x expected=%08x", ahb_htrans, ahb_haddr, SECOND_ADDR);
      $fatal(1, "stalled stream read lost address bits");
    end

    $display("axi4_to_ahb stream read stall repro passed");
    $finish;
  end
endmodule
