    cfg.clk_rst_vif.wait_clks(1_000);

    csr_rd(.ptr(ral.host_fifo_status.fmtlvl), .value(fmt_lvl), .backdoor(1'b1));
    csr_rd(.ptr(ral.status.hostidle), .value(hostidle));
