tb_script:
#!/bin/bash
set -u
set -o pipefail

cd /home/opentitan || exit 1

if [[ -f /etc/opentitan_tools_path.sh ]]; then
  source /etc/opentitan_tools_path.sh
fi

TEST_NAME="mbx_host_abort_ack_reset"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"

emit_result() {
  local rc="$1"
  echo "HWE_BENCH_RESULTS_START"
  if [[ "${rc}" -eq 0 ]]; then
    echo "TEST: ${TEST_NAME} ... PASS"
  else
    echo "TEST: ${TEST_NAME} ... FAIL"
  fi
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  logic clk;
  logic rst_ni;

  logic ib_mbx_range_valid;
  logic ib_hostif_abort_ack;
  logic ib_mbx_error_set;
  logic ib_sysif_control_abort_set;
  logic ib_sys_read_all;
  logic ib_writer_close_mbx;
  logic ib_writer_last_word_written;
  logic ib_writer_write_valid;
  logic ib_mbx_empty;
  logic ib_mbx_write;
  logic ib_mbx_read;
  logic ib_mbx_sys_abort;
  logic ib_mbx_ready_update;
  logic ib_mbx_ready;
  logic ib_mbx_irq_ready;
  logic ib_mbx_irq_abort;
  logic ib_mbx_state_error;

  logic ob_mbx_range_valid;
  logic ob_hostif_abort_ack;
  logic ob_mbx_error_set;
  logic ob_sysif_control_abort_set;
  logic ob_sys_read_all;
  logic ob_writer_close_mbx;
  logic ob_writer_last_word_written;
  logic ob_writer_write_valid;
  logic ob_mbx_empty;
  logic ob_mbx_write;
  logic ob_mbx_read;
  logic ob_mbx_sys_abort;
  logic ob_mbx_ready_update;
  logic ob_mbx_ready;
  logic ob_mbx_irq_ready;
  logic ob_mbx_irq_abort;
  logic ob_mbx_state_error;

  mbx_fsm #(
    .CfgOmbx(1'b0)
  ) u_imbx_fsm (
    .clk_i(clk),
    .rst_ni(rst_ni),
    .mbx_range_valid_i(ib_mbx_range_valid),
    .hostif_abort_ack_i(ib_hostif_abort_ack),
    .mbx_error_set_i(ib_mbx_error_set),
    .sysif_control_abort_set_i(ib_sysif_control_abort_set),
    .sys_read_all_i(ib_sys_read_all),
    .writer_close_mbx_i(ib_writer_close_mbx),
    .writer_last_word_written_i(ib_writer_last_word_written),
    .writer_write_valid_i(ib_writer_write_valid),
    .mbx_empty_o(ib_mbx_empty),
    .mbx_write_o(ib_mbx_write),
    .mbx_read_o(ib_mbx_read),
    .mbx_sys_abort_o(ib_mbx_sys_abort),
    .mbx_ready_update_o(ib_mbx_ready_update),
    .mbx_ready_o(ib_mbx_ready),
    .mbx_irq_ready_o(ib_mbx_irq_ready),
    .mbx_irq_abort_o(ib_mbx_irq_abort),
    .mbx_state_error_o(ib_mbx_state_error)
  );

  mbx_fsm #(
    .CfgOmbx(1'b1)
  ) u_ombx_fsm (
    .clk_i(clk),
    .rst_ni(rst_ni),
    .mbx_range_valid_i(ob_mbx_range_valid),
    .hostif_abort_ack_i(ob_hostif_abort_ack),
    .mbx_error_set_i(ob_mbx_error_set),
    .sysif_control_abort_set_i(ob_sysif_control_abort_set),
    .sys_read_all_i(ob_sys_read_all),
    .writer_close_mbx_i(ob_writer_close_mbx),
    .writer_last_word_written_i(ob_writer_last_word_written),
    .writer_write_valid_i(ob_writer_write_valid),
    .mbx_empty_o(ob_mbx_empty),
    .mbx_write_o(ob_mbx_write),
    .mbx_read_o(ob_mbx_read),
    .mbx_sys_abort_o(ob_mbx_sys_abort),
    .mbx_ready_update_o(ob_mbx_ready_update),
    .mbx_ready_o(ob_mbx_ready),
    .mbx_irq_ready_o(ob_mbx_irq_ready),
    .mbx_irq_abort_o(ob_mbx_irq_abort),
    .mbx_state_error_o(ob_mbx_state_error)
  );

  always #5 clk = ~clk;

  task automatic step;
    begin
      @(posedge clk);
      #1;
    end
  endtask

  task automatic fail(input string msg);
    begin
      $display("TB_STATUS: FAIL: %s", msg);
      $finish;
    end
  endtask

  initial begin
    clk = 1'b0;
    rst_ni = 1'b0;

    ib_mbx_range_valid = 1'b0;
    ib_hostif_abort_ack = 1'b0;
    ib_mbx_error_set = 1'b0;
    ib_sysif_control_abort_set = 1'b0;
    ib_sys_read_all = 1'b0;
    ib_writer_close_mbx = 1'b0;
    ib_writer_last_word_written = 1'b0;
    ib_writer_write_valid = 1'b0;

    ob_mbx_range_valid = 1'b0;
    ob_hostif_abort_ack = 1'b0;
    ob_mbx_error_set = 1'b0;
    ob_sysif_control_abort_set = 1'b0;
    ob_sys_read_all = 1'b0;
    ob_writer_close_mbx = 1'b0;
    ob_writer_last_word_written = 1'b0;
    ob_writer_write_valid = 1'b0;

    repeat (2) step();
    rst_ni = 1'b1;
    ib_mbx_range_valid = 1'b1;
    ob_mbx_range_valid = 1'b1;
    step();

    if (ib_mbx_empty !== 1'b1 || ib_mbx_write !== 1'b0 || ib_mbx_sys_abort !== 1'b0) begin
      fail("Inbound FSM did not start in idle state");
    end
    if (ob_mbx_empty !== 1'b1 || ob_mbx_read !== 1'b0) begin
      fail("Outbound FSM did not start in idle state");
    end

    ib_writer_write_valid = 1'b1;
    step();
    ib_writer_write_valid = 1'b0;

    if (ib_mbx_write !== 1'b1 || ib_mbx_empty !== 1'b0) begin
      fail("Inbound FSM did not enter write state");
    end

    ib_hostif_abort_ack = 1'b1;
    step();
    if (ib_mbx_empty !== 1'b1 || ib_mbx_write !== 1'b0 || ib_mbx_sys_abort !== 1'b0) begin
      fail("Inbound host abort acknowledge did not reset the FSM");
    end
    ib_hostif_abort_ack = 1'b0;
    step();

    ib_writer_write_valid = 1'b1;
    step();
    ib_writer_write_valid = 1'b0;
    if (ib_mbx_write !== 1'b1) begin
      fail("Inbound FSM did not recover after host abort acknowledge");
    end

    ob_writer_close_mbx = 1'b1;
    step();
    if (ob_mbx_read !== 1'b1) begin
      fail("Outbound FSM did not enter read state");
    end
    ob_writer_close_mbx = 1'b0;

    ob_hostif_abort_ack = 1'b1;
    step();
    if (ob_mbx_empty !== 1'b1 || ob_mbx_read !== 1'b0) begin
      fail("Outbound host abort acknowledge did not return the FSM to idle");
    end
    if (ob_mbx_ready_update !== 1'b1 || ob_mbx_ready !== 1'b0) begin
      fail("Outbound host abort acknowledge did not clear ready");
    end
    ob_hostif_abort_ack = 1'b0;
    step();

    ob_writer_close_mbx = 1'b1;
    step();
    if (ob_mbx_read !== 1'b1) begin
      fail("Outbound FSM did not recover after host abort acknowledge");
    end

    $display("TB_STATUS: PASS");
    $finish;
  end
endmodule
EOF

set +e
vcs -full64 -sverilog -timescale=1ns/1ps +define+SYNTHESIS \
  +incdir+/home/opentitan/hw/ip/prim/rtl \
  -o "${TB_DIR}/simv" \
  "${TB_DIR}/tb.sv" \
  /home/opentitan/hw/vendor/lowrisc_ibex/dv/uvm/core_ibex/common/prim/prim_flop.sv \
  /home/opentitan/hw/ip/prim_generic/rtl/prim_generic_flop.sv \
  /home/opentitan/hw/ip/mbx/rtl/mbx_fsm.sv \
  -l "${COMPILE_LOG}"
compile_rc=$?

if [[ "${compile_rc}" -ne 0 ]]; then
  emit_result "${compile_rc}"
  exit "${compile_rc}"
fi

"${TB_DIR}/simv" -l "${RUN_LOG}"
sim_rc=$?

if [[ "${sim_rc}" -eq 0 ]] && grep -Eq '^TB_STATUS: PASS$' "${RUN_LOG}" &&
   ! grep -Eq '^TB_STATUS: FAIL:' "${RUN_LOG}"; then
  run_rc=0
else
  run_rc=1
fi
set -e

emit_result "${run_rc}"
exit "${run_rc}"

