from pathlib import Path
import sys


def ensure_append(path: Path, line: str) -> None:
    text = path.read_text(encoding="utf-8")
    if line in text:
        return
    path.write_text(text.rstrip() + "\n\n" + line + "\n", encoding="utf-8")


def ensure_insert_after(path: Path, needle: str, insertion: str) -> None:
    text = path.read_text(encoding="utf-8")
    if insertion.strip() in text:
        return
    if needle not in text:
        raise RuntimeError(f"missing anchor in {path}")
    path.write_text(text.replace(needle, needle + insertion, 1), encoding="utf-8")


try:
    ensure_append(
        Path("/home/opentitan/hw/ip/i2c/dv/env/seq_lib/i2c_vseq_list.sv"),
        '`include "i2c_host_sda_interference_repro_vseq.sv"',
    )
    ensure_insert_after(
        Path("/home/opentitan/hw/ip/i2c/dv/env/i2c_env.core"),
        "      - seq_lib/i2c_host_stress_all_vseq.sv: {is_include_file: true}\n",
        "      - seq_lib/i2c_host_sda_interference_repro_vseq.sv: {is_include_file: true}\n",
    )
except Exception as err:
    print(err, file=sys.stderr)
    sys.exit(1)
