    tick();
  endtask

  task automatic push_data_byte(input logic [7:0] value);
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    rx_addr_i = DevAddr;
    rx_endp_i = Endpoint[3:0];
    rx_data_put_i = 1'b1;
    rx_data_i = value;
    tick();
    if (!out_ep_data_put_o || out_ep_data_o != value) begin
      $fatal(1, "Payload byte was not accepted");
    end
  endtask

  task automatic finish_data_packet(
    input logic [3:0] data_pid,
    output logic rollback_seen,
    output logic ack_commit_seen
  );
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    rx_pkt_end_i = 1'b1;
    rx_pkt_valid_i = 1'b1;
    rx_pid_i = data_pid;
    rx_addr_i = DevAddr;
    rx_endp_i = Endpoint[3:0];
    #1;
    rollback_seen = out_ep_rollback_o && tx_pkt_start_o && (tx_pid_o == UsbPidAck);
    @(posedge clk_48mhz_i);
    #1;
    ack_commit_seen = out_ep_acked_o && tx_pkt_start_o && (tx_pid_o == UsbPidAck);
  endtask

  task automatic fail_test(input string message);
    $display("TB_FAIL: %0s", message);
    $finish;
  endtask

  task automatic send_out_transfer(
    input logic [3:0] data_pid,
    input bit expect_commit
  );
    logic rollback_seen;
    logic ack_commit_seen;

    send_out_token();
    drive_idle_cycle();
    start_data_phase();
    push_data_byte(8'ha5);
    finish_data_packet(data_pid, rollback_seen, ack_commit_seen);
    drive_idle_cycle();

    if (expect_commit) begin
      if (rollback_seen || !ack_commit_seen) begin
        fail_test($sformatf("Expected committed %0s packet, saw rollback=%0b commit=%0b",
                            (data_pid == UsbPidData0) ? "DATA0" : "DATA1",
                            rollback_seen, ack_commit_seen));
      end
    end else begin
      if (!rollback_seen || ack_commit_seen) begin
        fail_test($sformatf("Expected retransmit handling for %0s packet, saw rollback=%0b commit=%0b",
                            (data_pid == UsbPidData0) ? "DATA0" : "DATA1",
                            rollback_seen, ack_commit_seen));
      end
    end
  endtask

  initial begin
    rst_ni = 1'b0;
    link_reset_i = 1'b0;
    link_active_i = 1'b1;
    dev_addr_i = DevAddr;
    out_ep_enabled_i = 2'b10;
    out_ep_control_i = 2'b00;
    out_ep_full_i = 2'b00;
    out_ep_stall_i = 2'b00;
    out_ep_iso_i = 2'b00;
    data_toggle_clear_i = 2'b00;
    tx_pkt_end_i = 1'b0;
    clear_rx_inputs();

    repeat (3) tick();
    rst_ni = 1'b1;
    repeat (2) tick();

    // First DATA0 packet commits and moves the endpoint toggle to DATA1.
    send_out_transfer(UsbPidData0, 1'b1);

    // A suspend window must not clear the OUT data toggle.
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    link_active_i = 1'b0;
    tick();
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    link_active_i = 1'b1;
    tick();

    // After resume, the next new packet for the endpoint may legitimately be DATA1.
    // The buggy base revision treats it as a retransmission and rolls it back.
    send_out_transfer(UsbPidData1, 1'b1);

    $display("TB_PASS: USB OUT data toggle was retained across suspend");
    $finish(0);
  end
endmodule
EOF

vcs -full64 -sverilog -timescale=1ns/1ps \
  +incdir+/home/opentitan/hw/ip/prim/rtl \
  +incdir+/home/opentitan/hw/ip/usbdev/rtl \
  -Mdir="$TB_DIR/csrc" \
  -o "$TB_DIR/simv" \
  /home/opentitan/hw/ip/usbdev/rtl/usb_consts_pkg.sv \
  /home/opentitan/hw/ip/usbdev/rtl/usb_fs_nb_out_pe.sv \
  "$TB_DIR/tb.sv" \
  -l "$TB_DIR/compile.log"

set +e
"$TB_DIR/simv" -l "$TB_DIR/run.log"
rc=$?
set -e

if [ "$rc" -eq 0 ]; then
  if grep -q '^TB_FAIL:' "$TB_DIR/run.log"; then
    rc=1
  elif grep -q '^TB_PASS:' "$TB_DIR/run.log"; then
    rc=0
  else
    echo "Testbench did not emit a terminal runtime marker" >&2
    rc=1
  fi
fi

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: $TEST_NAME ... PASS"
else
  echo "TEST: $TEST_NAME ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="usbdev_setup_priority_over_stall_response"
TB_ROOT="/home/opentitan/.tb_${TEST_NAME}"
SEQ_FILE="hw/ip/usbdev/dv/env/seq_lib/${TEST_NAME}_vseq.sv"
SIM_CFG="${TB_ROOT}/${TEST_NAME}_sim_cfg.hjson"
SCRATCH_ROOT="${TB_ROOT}/scratch"
SEED="6059828404840696268329756370818438228836193083784097444560659638759758565984"

mkdir -p "$TB_ROOT"

cat > "$SEQ_FILE" <<'EOF'
// Copyright lowRISC contributors (OpenTitan project).
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class usbdev_setup_priority_over_stall_response_vseq extends usbdev_base_vseq;
  `uvm_object_utils(usbdev_setup_priority_over_stall_response_vseq)

  `uvm_object_new

  virtual task body();
    buf_init();

    // Accept both OUT and SETUP traffic on EP0, but STALL the OUT transaction.
    configure_out_trans(ep_default);
    configure_setup_trans(ep_default);
    csr_wr(.ptr(ral.out_stall[0].endpoint[ep_default]), .value(1'b1));

    // A long OUT packet that is rejected with STALL must still roll back internal RX state.
    send_prnd_out_packet(ep_default, PidTypeData0, .randomize_length(1'b0), .num_of_bytes(64));
    check_response_matches(PidTypeStall);

    // The next SETUP transaction must still be received correctly.
    send_prnd_setup_packet(ep_default);
    check_response_matches(PidTypeAck);
    check_rx_packet(ep_default, .setup(1'b1), .exp_buffer_id(setup_buffer_id),
                    .exp_byte_data(m_data_pkt.data), .buffer_known(1'b1));
  endtask
endclass : usbdev_setup_priority_over_stall_response_vseq
EOF

if ! grep -q "${TEST_NAME}_vseq.sv" hw/ip/usbdev/dv/env/seq_lib/usbdev_vseq_list.sv; then
  sed -i '/`include "usbdev_setup_priority_vseq.sv"/i `include "usbdev_setup_priority_over_stall_response_vseq.sv"' \
    hw/ip/usbdev/dv/env/seq_lib/usbdev_vseq_list.sv
fi

if ! grep -q "seq_lib/${TEST_NAME}_vseq.sv" hw/ip/usbdev/dv/env/usbdev_env.core; then
  sed -i '/seq_lib\/usbdev_setup_priority_vseq.sv/i\      - seq_lib\/usbdev_setup_priority_over_stall_response_vseq.sv: {is_include_file: true}' \
    hw/ip/usbdev/dv/env/usbdev_env.core
fi

cat > "$SIM_CFG" <<'EOF'
{
  import_cfgs: ["{proj_root}/hw/ip/usbdev/dv/usbdev_sim_cfg.hjson"]
  tests: [
    {
      name: usbdev_setup_priority_over_stall_response
      uvm_test_seq: usbdev_setup_priority_over_stall_response_vseq
      reseed: 1
    }
  ]
}
EOF

rm -rf "$SCRATCH_ROOT"
mkdir -p "$SCRATCH_ROOT"

set +e
timeout 1800 ./util/dvsim/dvsim.py "$SIM_CFG" \
  -i "$TEST_NAME" \
  -t vcs \
  --fixed-seed "$SEED" \
  --scratch-root "$SCRATCH_ROOT" \
  -v m
rc=$?
set -e

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"
